CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, execution_id TEXT NOT NULL REFERENCES executions(id) ON DELETE CASCADE, actor_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, action TEXT NOT NULL, risk TEXT NOT NULL, argument_summary TEXT NOT NULL, estimated_cost NUMERIC, decision TEXT, decided_by TEXT REFERENCES users(id), decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS approvals_pending_idx ON approvals(decision,created_at DESC);
CREATE TABLE IF NOT EXISTS budgets (id TEXT PRIMARY KEY, scope_type TEXT NOT NULL, scope_id TEXT NOT NULL, token_limit BIGINT, cost_limit NUMERIC, tool_call_limit BIGINT, step_limit BIGINT, time_limit_ms BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(scope_type,scope_id));
CREATE TABLE IF NOT EXISTS execution_usage (execution_id TEXT PRIMARY KEY REFERENCES executions(id) ON DELETE CASCADE, input_tokens BIGINT, output_tokens BIGINT, cached_tokens BIGINT, reasoning_tokens BIGINT, actual_cost NUMERIC, estimated_cost NUMERIC, tool_calls BIGINT NOT NULL DEFAULT 0, steps BIGINT NOT NULL DEFAULT 0, duration_ms BIGINT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
